            new[] { (359u, DamageType.Bludgeon, true), (3905u, DamageType.Acid, false), (3906u, DamageType.Electric, false), (3907u, DamageType.Fire, false), (3908u, DamageType.Cold, false), (900181u, DamageType.Nether, false) },
            // Yaoji
            new[] { (361u, DamageType.Slash | DamageType.Pierce, true), (3909u, DamageType.Acid, false), (3910u, DamageType.Electric, false), (3911u, DamageType.Fire, false), (3912u, DamageType.Cold, false), (900182u, DamageType.Nether, false) },
